<h1>Relatórios de vendas</h1><form class="row g-2 mb-3"><input type="hidden" name="r" value="relatorios"><div class="col-md-4"><label class="form-label">Data inicial</label><input class="form-control" type="date" name="inicio" value="<?=htmlspecialchars($inicio)?>"></div><div class="col-md-4"><label class="form-label">Data final</label><input class="form-control" type="date" name="fim" value="<?=htmlspecialchars($fim)?>"></div><div class="col-md-4 align-self-end"><button class="btn btn-primary w-100">Filtrar</button></div></form><div class="alert alert-info">Total de vendas concluídas no período: <strong>R$ <?=number_format($total,2,',','.')?></strong></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Número</th><th>Data</th><th>Cliente</th><th>Total</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($vendas as $v): ?><tr><td>#<?=$v['id']?></td><td><?=date('d/m/Y H:i',strtotime($v['criado_em']))?></td><td><?=htmlspecialchars($v['cliente_nome']??'Consumidor não identificado')?></td><td>R$ <?=number_format((float)$v['total'],2,',','.')?></td><td><?=htmlspecialchars($v['status'])?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="/?r=relatorios&id=<?=$v['id']?>">Detalhes</a><?php if($v['status']==='concluida'): ?><form method="post" onsubmit="return confirm('Cancelar esta venda e devolver os itens ao estoque?')"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn btn-sm btn-danger" name="cancelar">Cancelar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$vendas): ?><tr><td colspan="6">Nenhuma venda encontrada no período.</td></tr><?php endif; ?></tbody></table></div>
